text:
Where responses come from
The survey asks for a ZIP code at the start of the demographic section, so we have one for 2034 of the 2872 survey respondents (the rest stopped before that point). Canvassing records the canvasser’s ZIP, not the respondent’s, so it tells us where conversations happened. Interviews are placed by the ZIP in each transcript’s header; a group session carries one ZIP for everyone in the room, and one transcript has no ZIP at all.


Show code
# USDA ERS 2020 Rural-Urban Commuting Area codes by ZIP code (Sept 2025
# release). Gives each ZIP its state and a 1-10 rurality code. Downloaded
# once into data/raw/reference/ (not committed).
ruca_path &lt;- here("data/raw/reference/ruca2020_zip.csv")
if (!file.exists(ruca_path)) {
  dir.create(dirname(ruca_path), showWarnings = FALSE)
  download.file(
    "https://www.ers.usda.gov/media/5444/2020-rural-urban-commuting-area-codes-zip-codes.csv",
    ruca_path, headers = c("User-Agent" = "Mozilla/5.0")
  )
}
zip_lookup &lt;- read_csv(ruca_path, col_types = cols(.default = "c")) |&gt;
  transmute(zip = ZIPCode, state = State, ruca = as.integer(PrimaryRUCA))
zip_state &lt;- select(zip_lookup, zip, state)

# a few people typed ZIP+4 ("97530-0524"); the first five digits are the ZIP
survey_state &lt;- survey |&gt;
  filter(!is.na(zip)) |&gt;
  mutate(zip = str_sub(zip, 1, 5)) |&gt;
  left_join(zip_lookup, by = "zip")

canvassing_state &lt;- canvassing |&gt;
  filter(!is.na(canvasser_zip)) |&gt;
  left_join(zip_state, by = c("canvasser_zip" = "zip"))

# ZIP from each transcript's header (verified 2026-09-17), entered by hand
# until the coalition provides an interview metadata sheet
interviews &lt;- tribble(
  ~transcript,                          ~format,                    ~zip,
  "nopii_grp-sf_00000_othr_20260801",   "group, short form",        "60174",
  "nopii_grp-lf_00000_othr_20260811",   "group, long form",         "49712",
  "nopii_idv-lf_00000_othr_20260818",   "individual, long form",    "60302",
  "nopii_ind-lf_00000_othr_20260819",   "individual, long form",    "48840",
  "nopii_idv-sf_00000_othr_20260821",   "individual, short form",   NA
)
interview_state &lt;- interviews |&gt;
  filter(!is.na(zip)) |&gt;
  left_join(zip_state, by = "zip")

states &lt;- tibble(
  state = c(state.abb, "DC"),
  state_name = c(state.name, "District of Columbia")
)

# adults (18+) per state from the ACS 2024 1-year, pulled once and cached
# like the national benchmarks below
acs_state_path &lt;- here("data/raw/reference/acs2024_state_adults.csv")
if (!file.exists(acs_state_path)) {
  tidycensus::get_acs(
    "state", variables = sprintf("B01001_%03d", c(7:25, 31:49)),
    year = 2024, survey = "acs1"
  ) |&gt;
    summarise(adults = sum(estimate), .by = NAME) |&gt;
    rename(state_name = NAME) |&gt;
    write_csv(acs_state_path)
}
state_adults &lt;- read_csv(acs_state_path, show_col_types = FALSE) |&gt;
  filter(state_name != "Puerto Rico") |&gt;
  mutate(share_us_adults = adults / sum(adults))

# The Century Foundation's 2024 care-policy report card grade for each state
# (Gutierrez et al. 2024), as tabulated in the Population Data Memo; entered
# by hand because the report card is not available as data
care_grades &lt;- read_csv(here("data/raw/reference/care_policy_grades_2024.csv"), show_col_types = FALSE)
failing_grades &lt;- c("F", "D-", "D", "D+")

state_counts &lt;- list(
  survey = survey_state,
  canvassing = canvassing_state,
  interviews = interview_state
) |&gt;
  imap(\(data, tool) count(filter(data, !is.na(state)), state, name = tool)) |&gt;
  reduce(full_join, by = "state") |&gt;
  full_join(states, by = "state") |&gt;
  mutate(
    state_name = coalesce(state_name, state),
    across(c(survey, canvassing, interviews), \(x) replace_na(x, 0L))
  ) |&gt;
  left_join(care_grades, by = "state_name") |&gt;
  left_join(select(state_adults, state_name, share_us_adults), by = "state_name") |&gt;
  mutate(share_survey = survey / sum(survey)) |&gt;
  arrange(desc(survey), state_name)

share_failing &lt;- \(x) sum(x[state_counts$care_policy_grade %in% failing_grades]) / sum(x)


Every state is listed, including those with no responses yet, so gaps are visible. Two columns give the comparison that matters for outreach: each state’s share of all survey respondents next to its share of US adults, so a state with a much smaller survey share than population share is one the campaign is under-reaching. The grade is the state’s score on the Century Foundation’s 2024 care-policy report card, which the coalition’s outreach guidance uses to prioritize states with D and F grades. Those states hold 61% of US adults and 47% of survey respondents so far. Click a column heading to sort.


Show code
state_counts |&gt;
  transmute(
    State = state_name, Grade = care_policy_grade,
    Survey = survey, `Share of survey` = share_survey, `Share of US adults` = share_us_adults,
    Canvassing = canvassing, Interviews = interviews
  ) |&gt;
  reactable(
    defaultSorted = list(Survey = "desc"),
    pagination = FALSE,
    striped = TRUE,
    compact = TRUE,
    searchable = TRUE,
    defaultColDef = colDef(footer = \(values) if (is.numeric(values)) sum(values) else "Total"),
    columns = list(
      State = colDef(minWidth = 160),
      Grade = colDef(maxWidth = 70, footer = ""),
      `Share of survey` = colDef(format = colFormat(percent = TRUE, digits = 1), footer = \(v) percent(sum(v), accuracy = 1)),
      `Share of US adults` = colDef(format = colFormat(percent = TRUE, digits = 1), footer = \(v) percent(sum(v), accuracy = 1))
    )
  )






9 survey ZIP codes and 2 canvasser ZIP codes did not match a real ZIP (for example, 00000) and are left out of the table.


Show code
state_counts |&gt;
  filter(survey &gt; 0) |&gt;
  slice_max(survey, n = 15) |&gt;
  mutate(state_name = fct_reorder(state_name, survey)) |&gt;
  ggplot(aes(survey, state_name)) +
  geom_col() +
  geom_text(aes(label = survey), hjust = -0.3, size = 3) +
  scale_x_continuous(expand = expansion(mult = c(0, .1))) +
  labs(
    title = "Survey respondents by state, top 15",
    subtitle = str_glue("Among {nrow(survey_state)} respondents who gave a ZIP code"),
    x = "Respondents", y = NULL
  )










Rural and urban
The same ZIP lookup classifies each ZIP code by how rural it is, using the Rural-Urban Commuting Area (RUCA) codes from the USDA Economic Research Service. The codes run from 1 (inside a metropolitan area) to 10 (rural, far from any town), based on where people in that ZIP commute to work. We group them two ways: a four-way split used in much rural health research, and the urban/rural split the coalition asked for (Jaimie Worker, Caring Across Generations, September 2026), where “rural” is RUCA 4 to 10. That is also the cut the Health Resources and Services Administration’s Federal Office of Rural Health Policy uses to define rural for its programs.


Show code
survey_state &lt;- survey_state |&gt;
  mutate(
    rurality = case_when(
      ruca %in% 1:3  ~ "Metropolitan (1-3)",
      ruca %in% 4:6  ~ "Micropolitan (4-6)",
      ruca %in% 7:9  ~ "Small town (7-9)",
      ruca == 10     ~ "Rural (10)"
    ) |&gt; factor(levels = c("Metropolitan (1-3)", "Micropolitan (4-6)", "Small town (7-9)", "Rural (10)")),
    urban_rural = if_else(ruca %in% 1:3, "Urban (RUCA 1-3)", "Rural (RUCA 4-10)") |&gt;
      factor(levels = c("Urban (RUCA 1-3)", "Rural (RUCA 4-10)"))
  )

survey_state |&gt;
  filter(!is.na(rurality)) |&gt;
  count(urban_rural, rurality, name = "respondents") |&gt;
  mutate(share = percent(respondents / sum(respondents), accuracy = 1)) |&gt;
  rename("Urban or rural" = urban_rural, "RUCA group" = rurality) |&gt;
  tbl()






Rural respondents are a smaller group, so splits within the rural categories are still thin. The urban/rural split is large enough to compare answers under the project’s subgroup standard (200 or more respondents per group). For example, what ideal care looks like:


Show code
rates_by(survey_state, "q6", urban_rural) |&gt;
  tbl()






One check on that definition. RUCA codes 2 and 3 are places within commuting range of a metropolitan core but outside it (suburbs and exurbs), and whether they count as urban or rural is a judgment call. The same question split three ways shows whether that choice matters: if the middle column looks like the first, the definition above is safe; if it looks like the last, counting 2 and 3 as rural would change the picture.


Show code
survey_state |&gt;
  mutate(ruca_group = case_when(
    ruca == 1        ~ "RUCA 1 (metro core)",
    ruca %in% 2:3    ~ "RUCA 2-3 (metro commuting)",
    ruca &gt;= 4        ~ "RUCA 4-10 (rural)"
  ) |&gt; factor(levels = c("RUCA 1 (metro core)", "RUCA 2-3 (metro commuting)", "RUCA 4-10 (rural)"))) |&gt;
  rates_by("q6", ruca_group) |&gt;
  tbl()

Connection to care
The first question asks about a person’s connection to care and routes them to one of five pathways. This decides which questions each person sees, so it shapes everything below. Current caregivers and care recipients are by far the largest group.


Show code
bind_rows(survey = survey, canvassing = canvassing, .id = "tool") |&gt;
  filter(!is.na(pathway)) |&gt;
  count(tool, pathway) |&gt;
  mutate(share = percent(n / sum(n), accuracy = 1), .by = tool) |&gt;
  pivot_wider(names_from = tool, values_from = c(n, share)) |&gt;
  select(pathway, survey_n = n_survey, survey_share = share_survey,
         canvassing_n = n_canvassing, canvassing_share = share_canvassing) |&gt;
  tbl()






The answers behind the pathways. People could choose more than one.


Show code
survey |&gt;
  selection_rates("q1") |&gt;
  plot_rates(
    "Connection to care (survey)",
    str_glue("Share of {nrow(filter(survey, !is.na(q1_child_now)))} respondents who answered; more than one allowed")
  )

What people are saying
For each question, the chart shows the share of people who were shown the question choosing each answer, with the number of people in parentheses. Because the pathways see different questions, the group behind each chart is different; the subtitle says who.

Challenges for current caregivers and care recipients


Show code
q2a &lt;- selection_rates(survey, "q2a")
plot_rates(
  q2a,
  "What challenges have you experienced with care?",
  str_glue("Survey, current pathway, {unique(q2a$n_shown)} respondents")
)











Supports that would make a difference for current caregivers and recipients


Show code
q3a &lt;- selection_rates(survey, "q3a")
plot_rates(
  q3a,
  "What care support would make a difference for you?",
  str_glue("Survey, current pathway, {unique(q3a$n_shown)} respondents")
)











Who helps most with care


Show code
q4a &lt;- selection_rates(survey, "q4a")
plot_rates(
  q4a,
  "What or who helps you most with care? (top 3)",
  str_glue("Survey, current pathway, {unique(q4a$n_shown)} respondents")
)











What ideal care would look like
Everyone sees this question regardless of pathway, so it has the widest base. It asks people to choose up to three answers, but the form does not enforce that: roughly four in ten respondents chose more, and some chose all eleven. The table shows shares two ways, among everyone and among only the people who kept to three or fewer. The order of the answers is nearly the same either way; what changes is how big the percentages are, and it is worth deciding which version to report.


Show code
q6_all &lt;- selection_rates(survey, "q6")

q6_n_chosen &lt;- survey |&gt;
  filter(!is.na(q6_affordable)) |&gt;
  mutate(n_chosen = rowSums(across(starts_with("q6_") & where(is.logical) & !q6_other))) |&gt;
  select(respondent_id, n_chosen)

q6_within &lt;- survey |&gt;
  semi_join(filter(q6_n_chosen, n_chosen &lt;= 3), by = "respondent_id") |&gt;
  selection_rates("q6")

plot_rates(
  q6_all,
  "What would ideal care support and services look like for you?",
  str_glue("Survey, all pathways, {unique(q6_all$n_shown)} respondents")
)











Show code
q6_all |&gt;
  select(label, everyone = rate) |&gt;
  left_join(select(q6_within, label, three_or_fewer = rate), by = "label") |&gt;
  arrange(desc(everyone)) |&gt;
  mutate(across(c(everyone, three_or_fewer), \(x) percent(x, accuracy = 1))) |&gt;
  rename(
    Answer = label,
    "Everyone ({unique(q6_all$n_shown)})" := everyone,
    "Chose 3 or fewer ({unique(q6_within$n_shown)})" := three_or_fewer
  ) |&gt;
  tbl()








Ideal care by respondent group
The same question, split by age and by disability status. Each column is one group; the number in the heading is how many people in that group answered. These splits follow the project’s standard for reporting on subgroups: a group with fewer than 50 respondents is not shown, a group with 50 to 199 is marked “interpret with caution,” and a group with 200 or more is reported plainly. With more responses these splits can extend to every question and every demographic.


Show code
rates_by(survey, "q6", age) |&gt;
  tbl()








Show code
rates_by(survey, "q6", disability) |&gt;
  tbl()








In their own words
Every choose-all-that-apply question has an “Other” box. Text written there is kept word for word and will be coded alongside the open-ended questions. Number of respondents who wrote something, by question:


Show code
survey |&gt;
  select(ends_with("_other_text")) |&gt;
  summarise(across(everything(), \(x) sum(!is.na(x)))) |&gt;
  pivot_longer(everything(), names_to = "question", values_to = "respondents") |&gt;
  mutate(question = str_remove(question, "_other_text")) |&gt;
  filter(respondents &gt; 0) |&gt;
  arrange(desc(respondents)) |&gt;
  tbl()

Interviews
Five interview transcripts have been delivered: two group sessions and three individual interviews, in Illinois and Michigan (one transcript carries no ZIP code). Interview content is being coded against the project codebook and reported in the coding dashboard.


Show code
interviews |&gt;
  left_join(zip_state, by = "zip") |&gt;
  left_join(states, by = "state") |&gt;
  select(transcript, format, zip, state = state_name) |&gt;
  tbl()

Data dictionary
The column names and answer lists above already describe every column in the clean files. This step writes them out as one table, with a row per column (or per answer of a single-answer question) and the question and answer text behind it, so anyone using the clean files can look up what a column means without reading the code.


Show code
# the dictionary shows the original wording of each question
question_text &lt;- c(
  col_map,
  col_map_canv[setdiff(names(col_map_canv), names(col_map))],
  col_map_canv_revised[c("screener", "hard_text")]
) |&gt;
  map_chr(\(x) x[1])
all_multiselect &lt;- c(multiselect_options, list(doorstep = doorstep_options))

dict_options &lt;- all_multiselect |&gt;
  imap(\(opts, q) tibble(
    column   = str_c(q, "_", c(names(opts), "other", "other_text")),
    question = unname(question_text[q]),
    # aliased options (form revisions) list every accepted wording
    option   = c(unname(map_chr(opts, str_flatten, collapse = " [or] ")),
                 "Other (any response not in the structured options)",
                 "Free text captured from other responses")
  )) |&gt;
  list_rbind()

dict_factors &lt;- list(survey, canvassing, canvassing_revised) |&gt;
  map(\(data) {
    data |&gt;
      select(where(is.factor)) |&gt;
      as.list() |&gt;
      imap(\(v, nm) tibble(
        column   = nm,
        question = unname(question_text[nm]),
        option   = levels(v)
      )) |&gt;
      list_rbind()
  }) |&gt;
  list_rbind() |&gt;
  distinct()

dictionary &lt;- bind_rows(
  dict_options,
  dict_factors,
  tibble(column = "hard_text", question = unname(question_text["hard_text"]),
         option = "Free text, kept verbatim (revised canvassing form)")
) |&gt;
  mutate(question = if_else(
    column == "pathway",
    "Derived from q1 (priority: current &gt; past &gt; future &gt; observer &gt; none)",
    question
  ))

write_csv(dictionary, here("data/processed/data-dictionary.csv"))


Search or page through the dictionary here. The Variables page presents the same information question by question.
